/// Calibration profile model for MacTouch.
///
/// A calibration profile stores manually entered or simulated coordinate
/// correspondences and the resulting affine transform parameters for a
/// specific display. Profiles are stored as versioned local JSON.
///
/// **Important**: Calibration samples in this MVP are NOT measured from a
/// touch sensor. They are manually entered or generated by the simulator.
library;

import '../core/calibration/affine_calibration.dart';

/// A single calibration profile associated with a display.
class CalibrationProfile {
  /// Unique profile identifier.
  final String id;

  /// Human-readable name.
  final String name;

  /// Display ID this profile is associated with (may be null for
  /// display-independent profiles).
  final String? displayId;

  /// Calibration samples (source → destination correspondences).
  final List<CalibrationSample> samples;

  /// Computed affine calibration result, if samples are sufficient.
  final AffineCalibrationResult? calibrationResult;

  /// ISO 8601 timestamp of creation.
  final String createdAt;

  /// ISO 8601 timestamp of last modification.
  final String modifiedAt;

  const CalibrationProfile({
    required this.id,
    required this.name,
    this.displayId,
    required this.samples,
    this.calibrationResult,
    required this.createdAt,
    required this.modifiedAt,
  });

  /// Create a copy with updated fields.
  CalibrationProfile copyWith({
    String? name,
    String? displayId,
    List<CalibrationSample>? samples,
    AffineCalibrationResult? calibrationResult,
    String? modifiedAt,
  }) {
    return CalibrationProfile(
      id: id,
      name: name ?? this.name,
      displayId: displayId ?? this.displayId,
      samples: samples ?? this.samples,
      calibrationResult: calibrationResult ?? this.calibrationResult,
      createdAt: createdAt,
      modifiedAt: modifiedAt ?? this.modifiedAt,
    );
  }

  /// Convert to JSON-serializable map.
  Map<String, dynamic> toJson() => {
        'id': id,
        'name': name,
        'displayId': displayId,
        'samples': samples
            .map((s) => {
                  'sourceX': s.sourceX,
                  'sourceY': s.sourceY,
                  'destX': s.destX,
                  'destY': s.destY,
                })
            .toList(),
        'calibrationResult': calibrationResult != null
            ? {
                'parameters': calibrationResult!.parameters,
                'rmsError': calibrationResult!.rmsError,
                'maxError': calibrationResult!.maxError,
                'sampleCount': calibrationResult!.sampleCount,
              }
            : null,
        'createdAt': createdAt,
        'modifiedAt': modifiedAt,
      };

  /// Create from JSON map.
  factory CalibrationProfile.fromJson(Map<String, dynamic> json) {
    final samplesJson = json['samples'] as List<dynamic>? ?? [];
    final samples = samplesJson
        .map((s) => CalibrationSample(
              sourceX: (s['sourceX'] as num).toDouble(),
              sourceY: (s['sourceY'] as num).toDouble(),
              destX: (s['destX'] as num).toDouble(),
              destY: (s['destY'] as num).toDouble(),
            ))
        .toList();

    AffineCalibrationResult? calibResult;
    final calibJson = json['calibrationResult'] as Map<String, dynamic>?;
    if (calibJson != null) {
      calibResult = AffineCalibrationResult(
        parameters: (calibJson['parameters'] as List<dynamic>)
            .map((p) => (p as num).toDouble())
            .toList(),
        rmsError: (calibJson['rmsError'] as num).toDouble(),
        maxError: (calibJson['maxError'] as num).toDouble(),
        sampleCount: calibJson['sampleCount'] as int,
      );
    }

    return CalibrationProfile(
      id: json['id'] as String,
      name: json['name'] as String,
      displayId: json['displayId'] as String?,
      samples: samples,
      calibrationResult: calibResult,
      createdAt: json['createdAt'] as String,
      modifiedAt: json['modifiedAt'] as String,
    );
  }
}
